mapper.update:
UPDATE t_client_application SET organization_type_code=#{organizationTypeCode},
    schema_id=#{schemaId},update_time=#{now}
    WHERE application_id=#{applicationId} AND active_slot=1 AND status IN ('DRAFT','RETURNED')

UPDATE t_individual_profile SET update_time=#{now}
    ,given_name=#{changes[individual_givenName],jdbcType=VARCHAR}
    ,middle_name=#{changes[individual_middleName],jdbcType=VARCHAR}
    ,family_name=#{changes[individual_familyName],jdbcType=VARCHAR}
    ,birth_date=#{changes[individual_birthDate],jdbcType=DATE}
    ,nationality_country=#{changes[individual_nationalityCountry],jdbcType=VARCHAR}
    ,residence_country=#{changes[individual_residenceCountry],jdbcType=VARCHAR}
    ,birth_place=#{changes[individual_birthPlace],jdbcType=VARCHAR}
    ,birth_country=#{changes[individual_birthCountry],jdbcType=VARCHAR}
    ,gender=#{changes[individual_gender],jdbcType=VARCHAR}
    ,source_of_funds_code=#{changes[individual_sourceOfFundsCode],jdbcType=VARCHAR}
    ,pep_self_declared=#{changes[individual_pepSelfDeclared],jdbcType=TINYINT}
    WHERE profile_id=#{profileId}

UPDATE t_organization_profile SET update_time=#{now}
    ,legal_name=#{changes[organization_legalName],jdbcType=VARCHAR}
    ,trade_name=#{changes[organization_tradeName],jdbcType=VARCHAR}
    ,incorporation_country=#{changes[organization_incorporationCountry],jdbcType=VARCHAR}
    ,organization_type=#{changes[organization_organizationType],jdbcType=VARCHAR}
    ,incorporation_date=#{changes[organization_incorporationDate],jdbcType=DATE}
    ,registration_authority_code=#{changes[organization_registrationAuthorityCode],jdbcType=VARCHAR}
    ,license_expiry_date=#{changes[organization_licenseExpiryDate],jdbcType=DATE}
    ,listed_company=#{changes[organization_listedCompany],jdbcType=TINYINT}
    WHERE profile_id=#{profileId}

UPDATE t_party_address SET update_time=#{now}
    ,address_line1=#{changes[address_addressLine1],jdbcType=VARCHAR}
    ,address_line2=#{changes[address_addressLine2],jdbcType=VARCHAR}
    ,city=#{changes[address_city],jdbcType=VARCHAR}
    ,state_or_province=#{changes[address_stateOrProvince],jdbcType=VARCHAR}
    ,postal_code=#{changes[address_postalCode],jdbcType=VARCHAR}
    ,country_code=#{changes[address_countryCode],jdbcType=VARCHAR}
    ,building_number=#{changes[address_buildingNumber],jdbcType=VARCHAR}
    ,additional_number=#{changes[address_additionalNumber],jdbcType=VARCHAR}
    ,district=#{changes[address_district],jdbcType=VARCHAR}
    ,po_box=#{changes[address_poBox],jdbcType=VARCHAR}
    ,address_format_code=#{changes[address_addressFormatCode],jdbcType=VARCHAR}
    WHERE profile_id=#{profileId} AND address_type=#{addressType}

UPDATE t_party_profile_identifier SET update_time=#{now}
    ,identifier_type=#{changes[identifier_identifierType],jdbcType=VARCHAR}
    ,issuing_country=#{changes[identifier_issuingCountry],jdbcType=VARCHAR}
    ,identifier_vault_token=#{changes[identifier_identifierVaultToken],jdbcType=VARCHAR}
    ,public_identifier_value=#{changes[identifier_publicIdentifierValue],jdbcType=VARCHAR}
    ,identifier_masked_value=#{changes[identifier_identifierMaskedValue],jdbcType=VARCHAR}
    ,identifier_check_result=#{changes[identifier_identifierCheckResult],jdbcType=VARCHAR}
    ,issue_date=#{changes[identifier_issueDate],jdbcType=DATE}
    ,expiry_date=#{changes[identifier_expiryDate],jdbcType=DATE}
    WHERE profile_id=#{profileId} AND identity_key_id IS NULL

UPDATE t_client_business_profile SET update_time=#{now}
    ,business_model_code=#{changes[business_businessModelCode],jdbcType=VARCHAR}
    ,website_url=#{changes[business_websiteUrl],jdbcType=VARCHAR}
    ,business_description=#{changes[business_businessDescription],jdbcType=VARCHAR}
    ,expected_volume=#{changes[business_expectedVolume],jdbcType=DECIMAL}
    ,expected_ticket=#{changes[business_expectedTicket],jdbcType=DECIMAL}
    ,currency=#{changes[business_currency],jdbcType=VARCHAR}
    WHERE client_id=#{clientId}
